"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["72502"],{22577(e){e.exports=JSON.parse('{"id":"FIN-800","slug":"free-trade","term":"Free Trade","also_known_as":[],"difficulty":"Intermediate","definition":"Free trade is international trade with few or no government-imposed barriers, such as tariffs, quotas or import restrictions, allowing goods and services to move freely between countries.","explanation":["The case for free trade rests on comparative advantage. When countries specialise in producing what they are relatively best at and trade with each other, total output rises, consumers get access to a wider range of goods at lower prices, and businesses can sell to larger markets.","Countries often promote free trade through agreements. Some are regional, such as the single market of the European Union, while others are bilateral agreements between two countries. The World Trade Organization sets rules for trade among its members and works to reduce barriers.","For example, a free trade agreement might remove tariffs on cars, food and machinery traded between two countries, making those goods cheaper for consumers and businesses in both.","Free trade also has costs and critics. Some industries and workers face strong foreign competition and may lose jobs, especially in regions dependent on those industries. Critics also raise concerns about dependence on foreign suppliers for important goods and about weaker labour or environmental standards abroad. Most economists support free trade overall, while recognising the need to help those who lose out."],"note":"","total":1500,"prev":{"slug":"free-float","term":"Free Float"},"next":{"slug":"freemium-model","term":"Freemium Model"}}')}}]);